SELECT CASE WHEN d.budget >= 3316000 THEN 'high' WHEN d.budget >= 1093000 THEN 'mid' ELSE 'low' END AS budget_bucket, d.dept_name, ROUND((100 * SUM(CASE WHEN e.level = 'L4' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_l4 FROM employees e JOIN departments d ON d.id = e.dept_id WHERE d.location IN ('London', 'Bangkok', 'New York') GROUP BY CASE WHEN d.budget >= 3316000 THEN 'high' WHEN d.budget >= 1093000 THEN 'mid' ELSE 'low' END, d.dept_name ORDER BY budget_bucket
